function home_seo_parse_pairs($raw) {
    $lines = array_values(array_filter(array_map('trim', explode("\n", $raw)), 'strlen'));
    $pairs = [];
    for ($i = 0; $i + 1 < count($lines); $i += 2) {
        $pairs[] = [$lines[$i], $lines[$i + 1]];
    }
    return $pairs;
}

